## Literal Pattern Matching

Match on exact values — numbers, strings, or any discrete case.

### Numbers to Words

```xiom
fn number_name(n: Int) -> Str {
  return match n {
    1 => "one",
    2 => "two",
    3 => "three",
    4 => "four",
    5 => "five",
    _ => "many",
  };
}

fn main() -> Int {
  io.println(number_name(1));   // one
  io.println(number_name(4));   // four
  io.println(number_name(10));  // many
  return 0;
}
```

### Days of the Week

```xiom
fn day_name(day: Int) -> Str {
  return match day {
    1 => "Monday",
    2 => "Tuesday",
    3 => "Wednesday",
    4 => "Thursday",
    5 => "Friday",
    6 => "Saturday",
    7 => "Sunday",
    _ => "Invalid day",
  };
}

fn main() -> Int {
  io.println(day_name(3));  // Wednesday
  io.println(day_name(7));  // Sunday
  io.println(day_name(0));  // Invalid day
  return 0;
}
```

### Dice Combinations

```xiom
fn dice_result(a: Int, b: Int) -> Str {
  return match (a, b) {
    (1, 1) => "Snake eyes!",
    (6, 6) => "Boxcars!",
    (x, y) if x + y == 7 => "Lucky seven!",
    (x, y) if x == y => "Doubles: " + string.int_to_str(x) + "s",
    (x, y) => string.int_to_str(x) + " and " + string.int_to_str(y),
  };
}

fn main() -> Int {
  io.println(dice_result(1, 1));  // Snake eyes!
  io.println(dice_result(6, 6));  // Boxcars!
  io.println(dice_result(3, 4));  // Lucky seven!
  io.println(dice_result(2, 2));  // Doubles: 2s
  io.println(dice_result(2, 5));  // 2 and 5
  return 0;
}
```

### HTTP Status Codes

```xiom
fn status_message(code: Int) -> Str {
  return match code {
    200 => "OK",
    201 => "Created",
    301 => "Moved Permanently",
    404 => "Not Found",
    500 => "Internal Server Error",
    _ => "Unknown status",
  };
}

fn main() -> Int {
  io.println(status_message(200));  // OK
  io.println(status_message(404));  // Not Found
  io.println(status_message(418));  // Unknown status
  return 0;
}
```

