use xiom.io;

fn season_name(month: Int) -> Str {
  return match month {
    12 => "Winter",
    1 => "Winter",
    2 => "Winter",
    3 => "Spring",
    4 => "Spring",
    5 => "Spring",
    6 => "Summer",
    7 => "Summer",
    8 => "Summer",
    9 => "Autumn",
    10 => "Autumn",
    11 => "Autumn",
    _ => "Invalid month",
  };
}

fn is_weekend(day: Int) -> Str {
  return match day {
    6 => "Weekend!",
    7 => "Weekend!",
    1 => "Weekday",
    2 => "Weekday",
    3 => "Weekday",
    4 => "Weekday",
    5 => "Weekday",
    _ => "Invalid day",
  };
}

fn main() -> Int {
  io.println(season_name(3).to_str());
  io.println(season_name(7).to_str());
  io.println(season_name(11).to_str());
  io.println(season_name(13).to_str());
  io.println(is_weekend(5).to_str());
  io.println(is_weekend(6).to_str());
  io.println(is_weekend(0).to_str());
  return 0;
}
